#!/usr/bin/env python3
"""usage: gen_codegen_text_test.py lines.txt > tests/codegen_text_test.caspien (lines: check lines printed by a Java harness over caspien.bytecode.Text)."""
import sys
lines = [l for l in open(sys.argv[1]).read().split("\n") if l.strip()]
HEAD = '// Differential test of codegenCaspien/Text.caspien against caspien.bytecode.Text (check lines generated by gen_codegen_text_test.py from the Java class).\nimport "../stdlib/libc.caspien"\nimport "../stdlib/gt/*"\nimport "../Codegen/src/main/java/caspien/codegen/codegenCaspien/Text.caspien"\n\nfunc check(name: static imut string, ok: imut bool) void{\n\tunsafe extern{\n\t\tif ok{ printf("PASS %s\\n", name) }\n\t\telse{ printf("FAIL %s\\n", name) }\n\t}\n}\n\nfunc t_digits(a: static imut string) mut bool{\n\t?catch(e){ return false }\n\tlet s = mut ? new String(a)\n\tlet r = mut false\n\tmatch Some(s){ r = Text.isDigits(s) }\n\treturn r\n}\n\nfunc t_dec(a: static imut string) mut bool{\n\t?catch(e){ return false }\n\tlet s = mut ? new String(a)\n\tlet r = mut false\n\tmatch Some(s){ r = Text.isDecimalNumber(s) }\n\treturn r\n}\n\nfunc t_pref(a: static imut string, p: static imut string) mut bool{\n\t?catch(e){ return false }\n\tlet s = mut ? new String(a)\n\tlet pp = mut ? new String(p)\n\tlet r = mut false\n\tmatch Some(s){\n\t\tmatch Some(pp){\n\t\t\tr = try Text.isPrefixedDigits(s, pp) catch(err){ return false }\n\t\t}\n\t}\n\treturn r\n}\n\nfunc t_word(t: static imut string, n: static imut string, sf: static imut string, d: imut bool) mut bool{\n\t?catch(e){ return false }\n\tlet a = mut ? new String(t)\n\tlet b = mut ? new String(n)\n\tlet c = mut ? new String(sf)\n\tlet r = mut false\n\tmatch Some(a){\n\t\tmatch Some(b){\n\t\t\tmatch Some(c){\n\t\t\t\tr = Text.containsWord(a, b, c, d)\n\t\t\t}\n\t\t}\n\t}\n\treturn r\n}\n'
print(HEAD)
parts = [lines[i:i + 120] for i in range(0, len(lines), 120)]
for k, ps in enumerate(parts):
    print("func part%d() void{" % k)
    print("\n".join(ps))
    print("}\n")
print("func main() void{")
for k in range(len(parts)):
    print("\tpart%d()" % k)
print("}")
